<template><a-card v-if="canRead"><a-button v-if="canWrite" @click="openCreate">Create</a-button><div v-if="errorMessage">{{ errorMessage }}</div><a-table :columns="columns" :data-source="table.items.value" :loading="table.loading.value" :pagination="false"><template #bodyCell="{column,record}"><template v-if="column.key==='actions'"><a v-if="canWrite" @click="openEdit(record)">Edit</a><a-popconfirm v-if="canDelete" @confirm="remove(record)"><a>Delete</a></a-popconfirm></template></template></a-table><a-pagination :current="table.page.value" :page-size="table.pageSize.value" :total="table.total.value" @change="table.setPage"/></a-card></template>
<script setup lang="ts">
import{computed,inject,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{usePermission}from'@/hooks/usePermission';import{useTable}from'@/hooks/useTable';import type{ObservabilityDashboardApi}from'@/api/observability/dashboard';import type{Dashboard}from'@/types/observability';const api=inject<ObservabilityDashboardApi>('observabilityDashboardApi')!,router=useRouter(),p=usePermission();const canRead=computed(()=>p.has('observability:dashboard:read')),canWrite=computed(()=>p.has('observability:dashboard:write')),canDelete=computed(()=>p.has('observability:dashboard:delete')),errorMessage=ref('');const columns=[{key:'name',title:'Name',dataIndex:'name'},{key:'refresh',title:'Refresh',dataIndex:'refresh_interval_s'},{key:'range',title:'Range',dataIndex:'time_range'},{key:'actions',title:'Actions'}];const table=useTable<Dashboard,{}>({fetcher:async({page,pageSize})=>{try{const x=await api.list({page,page_size:pageSize});errorMessage.value='';return{items:x.items,total:x.total}}catch(error){errorMessage.value=error instanceof Error?error.message:'network.error';throw error}}});function openCreate(){void router.push('/observability/dashboards/create')}function openEdit(row:Dashboard){void router.push(`/observability/dashboards/${row.id}/edit`)}async function remove(row:Dashboard){try{await api.remove(row.id);await table.reload()}catch(error){errorMessage.value=error instanceof Error?error.message:'network.error'}}onMounted(()=>void table.reload().catch(()=>undefined));defineExpose({canRead,canWrite,canDelete,errorMessage,table,openCreate,openEdit,remove})
</script>
